import Foundation
import Darwin
func проверить(_ условие:@autoclosure ()->Bool,_ имя:String) { if !условие() { let d=Data(("ОТКАЗ "+имя+"\n").utf8); _=d.withUnsafeBytes { Darwin.write(STDERR_FILENO,$0.baseAddress,$0.count) }; Darwin._exit(1) } }
let первая=Data("{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"id\":\"native-1\",\"text\":\"same\"}}\n".utf8)
let вторая=Data("{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"id\":\"native-2\",\"text\":\"same\"}}\n".utf8)
let безID=Data("{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\"}}\n".utf8)
let хвост=Data("{\"type\":".utf8)
проверить(разобратьПрефикс(первая,источник:"bad\0source",прежний:nil) == .удержать,"NUL источника")
guard case let .снимок(начальный)=разобратьПрефикс(первая+вторая+безID+хвост,источник:"synthetic",прежний:nil) else { проверить(false,"чтение"); exit(1) }
проверить(начальный.строки.count==3 && начальный.хвостНеизвестен && начальный.хвост==хвост && начальный.контроль.граница==первая.count+вторая.count+безID.count,"обрамление")
проверить(начальный.строки[0].нативныйID=="native-1" && начальный.строки[1].нативныйID=="native-2" && начальный.строки[2].нативныйID==nil,"ID")
проверить(начальный.строки[0].позиционнаяПривязка != начальный.строки[1].позиционнаяПривязка && начальный.строки[0].позиционнаяПривязка != "native-1","позиция и ID")
проверить(начальный.строки[2].причинаНеизвестности=="нет подтверждённого ID" && начальный.строки[0].причинаНеизвестности=="происхождение не подтверждено","UNKNOWN")
let дополнение=Data("\"x\"}\n".utf8)
guard case let .снимок(продолжение)=разобратьПрефикс(первая+вторая+безID+хвост+дополнение,источник:"synthetic",прежний:начальный.контроль) else { проверить(false,"продолжение"); exit(1) }
проверить(продолжение.хвост.isEmpty && продолжение.строки.count==4 && продолжение.строки[3].нативныйID==nil,"завершённый хвост")
var изменённые=первая+вторая+безID+хвост; изменённые[0]=32
проверить(разобратьПрефикс(изменённые,источник:"synthetic",прежний:начальный.контроль) == .удержать,"дрейф префикса")
проверить(разобратьПрефикс(первая+вторая+безID+хвост,источник:"other",прежний:начальный.контроль) == .удержать,"чужой источник")
let конфликт=Data("{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"id\":\"native-1\",\"text\":\"different\"}}\n".utf8)
проверить(разобратьПрефикс(первая+конфликт,источник:"synthetic",прежний:nil) == .удержать,"конфликт ID")
guard case let .снимок(повтор)=разобратьПрефикс(первая+первая,источник:"synthetic",прежний:nil) else { проверить(false,"повтор"); exit(1) }
проверить(повтор.строки.count==2 && повтор.строки[0].нативныйID==повтор.строки[1].нативныйID && повтор.строки[0].позиционнаяПривязка != повтор.строки[1].позиционнаяПривязка,"повтор и позиции")
print("ПРОЙДЕНО синтетический байтовый префикс; допуск отсутствует")
